fn main() {
 let path=std::path::PathBuf::from(std::env::args().nth(1).unwrap());
 let retain=std::env::args().nth(2).as_deref()==Some("retained");
 let profile=toucan::CompilerProfile::new(toucan::Target::X86_64UnknownLinuxGnu,toucan::Compiler::Clang).unwrap();
 let mut config=toucan::Config::with_profile(profile);
 config.preprocessor.max_tokens=2_000_000;
 config.analysis.retain_code=retain;
 config.analysis.limits=toucan::semantic::checked::Limits{nodes:2_000_000,edges:8_000_000,payload_bytes:128*1024*1024};
 match toucan::parse_file(&path,&config) {Ok(a)=>println!("accepted {} declarations; retained {}",a.unit().declarations.len(),a.checked().is_some()),Err(e)=>{eprintln!("{e}");std::process::exit(1)}}
}
